,{"hash":"4e13062d549eadb52afd7b4c54a79c118b70e8a057e8d61939ec5db1b1946a6d","key":"ff3217275e90181879f6c3f331938da31f1d27369437ea448d289762c4301e28","location_type":"site","locations_text":"[{\"city\":\"St. Louis\",\"latitude\":38.635699,\"longitude\":-90.244582,\"precision\":\"city\",\"state\":\"MO\"}]"},{"hash":"b95af2c1ed5931fe89524488894b9c1d90484be1841577ce505c9b63f789c27f","key":"1d9609d54082c1ea29420456c4ea6f472bb020b11e86114c85e2cb2befe6c8f1","location_type":"site","locations_text":"[{\"city\":\"Annandale\",\"latitude\":38.830261,\"longitude\":-77.214454,\"precision\":\"zip\",\"state\":\"VA\",\"zip\":\"22003\"}]"},{"hash":"4d6fdc14735d6d0c713eb6e1a664674783afd8e18c1840597defd590471e1cc9","key":"5f6e3566d65829a279f504b655929249359851ff342e8302c53ad8fa132bd0fa","location_type":"site","locations_text":"[{\"city\":\"Eugene\",\"latitude\":44.067988,\"longitude\":-123.080181,\"precision\":\"zip\",\"state\":\"OR\",\"zip\":\"97401\"}]"},{"hash":"14b8c7f0aa80fd462c1a60ee730eabb91036f6255f30ff25d075210fb00b7ef8","key":"8e9eb0ec253314635a6a7b96a2a61dea71b7496567d372e243225ef6440e5d6b","location_type":"site","locations_text":"[{\"city\":\"Palmer\",\"latitude\":61.62442,\"longitude\":-148.982077,\"precision\":\"zip\",\"state\":\"AK\",\"zip\":\"99645\"}]"},{"hash":"8eca8b7435bdda6398fe02c4fc1d2c1a9343fb13c6152f65db5d8494b0baaa42","key":"935f5439cf99bbff5dd12ee1046659c9034009cbae0dd6da95067922d15d9170","location_type":"site","locations_text":"[{\"city\":\"Williston\",\"latitude\":44.429166,\"longitude\":-73.09631,\"precision\":\"zip\",\"state\":\"VT\",\"zip\":\"05495\"}]"}]$patches$::jsonb;
 p jsonb;
 original_row record;
 merged jsonb;
 payload_text text;
 content_text text;
 prior_offer_fp text;
BEGIN
 PERFORM selfpay_directory_sync.check_target();
 LOCK TABLE public.settings, public.batches, public.entries, public.offers, public.publish_events IN SHARE ROW EXCLUSIVE MODE;
 IF (SELECT value FROM public.settings WHERE key='active_batch') IS DISTINCT FROM old_batch THEN
  RAISE EXCEPTION 'Coordinate update stopped: active batch changed';
 END IF;
 IF (SELECT count(*) FROM public.entries WHERE batch_id=old_batch) <> 103
 OR (SELECT count(*) FROM public.offers WHERE batch_id=old_batch) <> 13 THEN
  RAISE EXCEPTION 'Coordinate update stopped: catalog counts changed';
 END IF;
 prior_offer_fp := selfpay_directory_sync.catalog_fingerprints(old_batch)->>'offer_fingerprint';
 IF prior_offer_fp IS DISTINCT FROM '2a3b5859b77acfcd406614c7d2f3c49d2a4d9877edd2ea4c957067c0956976cd' THEN
  RAISE EXCEPTION 'Coordinate update stopped: offer fingerprint changed';
 END IF;
 IF selfpay_directory_sync.catalog_fingerprints(old_batch)->>'entry_fingerprint'
 IS DISTINCT FROM 'a0c23f2d2019f448345824ef1e244efaaa3cf444f10b76256a7f9b4a71ad46aa' THEN
  RAISE EXCEPTION 'Coordinate update stopped: entry fingerprint changed';
 END IF;
 IF jsonb_array_length(patches)<>103 OR
 (SELECT count(DISTINCT value->>'key') FROM jsonb_array_elements(patches))<>103 THEN
  RAISE EXCEPTION 'Coordinate update stopped: invalid patch set';
 END IF;
 INSERT INTO public.batches(id,content_hash,source_name,created,status,report)
 VALUES(new_batch,'68e3ee66875e3d2766c5fda05ecd5a9f72c62d599b746b27237166a94700bee8','coordinate-backfill-2026-10-09',extract(epoch FROM clock_timestamp()),'staged',
 '{"entry_count":103,"offer_count":13,"added":0,"removed":0,"coordinate_only":true,"previous_batch":"8e7d7758-6c76-4fb3-9803-825cc1f77567"}');
 FOR p IN SELECT value FROM jsonb_array_elements(patches) LOOP
  SELECT * INTO STRICT original_row FROM public.entries WHERE batch_id=old_batch AND entry_key=p->>'key';
  IF original_row.content_hash IS DISTINCT FROM p->>'hash'
   OR original_row.payload::jsonb ?| ARRAY['locations','location_type'] THEN
   RAISE EXCEPTION 'Coordinate update stopped: source entry changed or already enriched';
  END IF;
  merged := original_row.payload::jsonb || jsonb_build_object('locations',(p->>'locations_text')::jsonb,'location_type',p->>'location_type');
  SELECT '{'||string_agg(to_jsonb(key)::text||':'||CASE WHEN key='locations' THEN p->>'locations_text' ELSE value::text END,',' ORDER BY key COLLATE "C")||'}'
   INTO payload_text FROM jsonb_each(merged);
  SELECT '{'||string_agg(to_jsonb(key)::text||':'||CASE WHEN key='locations' THEN p->>'locations_text' ELSE value::text END,',' ORDER BY key COLLATE "C")||'}'
   INTO content_text FROM jsonb_each(merged) WHERE key<>'row';
  IF (payload_text::jsonb - 'locations' - 'location_type') IS DISTINCT FROM original_row.payload::jsonb THEN
   RAISE EXCEPTION 'Coordinate update stopped: non-geography field changed';
  END IF;
  INSERT INTO public.entries(batch_id,entry_key,content_hash,payload)
   VALUES(new_batch,original_row.entry_key,encode(sha256(convert_to(content_text,'UTF8')),'hex'),payload_text);
 END LOOP;
 INSERT INTO public.offers(batch_id,id,entry_key,amount_cents,max_cents,price_type,payload)
 SELECT new_batch,id,entry_key,amount_cents,max_cents,price_type,payload FROM public.offers WHERE batch_id=old_batch;
 IF (SELECT count(*) FROM public.entries WHERE batch_id=new_batch)<>103 OR
 selfpay_directory_sync.catalog_fingerprints(new_batch)->>'offer_fingerprint' IS DISTINCT FROM prior_offer_fp THEN
  RAISE EXCEPTION 'Coordinate update stopped: preservation assertion failed';
 END IF;
 UPDATE public.batches SET status='published' WHERE id=new_batch;
 UPDATE public.settings SET value=new_batch WHERE key='active_batch' AND value=old_batch;
 IF NOT FOUND THEN RAISE EXCEPTION 'Coordinate update stopped: publication conflict'; END IF;
 INSERT INTO public.publish_events(batch_id,previous_batch,created,action)
 VALUES(new_batch,old_batch,extract(epoch FROM clock_timestamp()),'publish');
END
$coordinate_update$;
